// Service worker generated by `cargo rullst make:pwa`; served at /sw.js by src/pwa.rs.
// The application owns this file. It keeps only what is safe to show offline:
// it never stores a non-GET request, a cross-origin response or a response
// marked `Cache-Control: no-store` or `private`, so authenticated pages stay
// off the device. Rullst answers `no-store` unless a route opts into caching.
'use strict';

// src/pwa.rs replaces 'dev' with the package version: a new version installs
// a new worker and a new cache, and the old cache is removed on activation.
const VERSION = 'dev';
const CACHE_PREFIX = 'rullst-pwa-';
const CACHE = CACHE_PREFIX + VERSION;
const OFFLINE_URL = '/offline';
// The offline page must be stored; the listed static files are stored when present.
const PRECACHE = ['/offline'];

function storable(response) {
  if (!response || response.status !== 200 || response.type !== 'basic') return false;
  if ((response.headers.get('Vary') || '').trim() === '*') return false;
  const control = (response.headers.get('Cache-Control') || '').toLowerCase();
  return !/(^|[\s,])(no-store|private)(?=$|[\s,=])/.test(control);
}

// The rule Rullst's static file server uses for a year-long cache: a part of
// the file name holds 8-64 lowercase hex characters with a digit and a letter
// (app.3f9a2c1b.css, chunk-3f9a2c1b.js).
function isVersioned(pathname) {
  const name = pathname.slice(pathname.lastIndexOf('/') + 1);
  const dot = name.lastIndexOf('.');
  if (dot <= 0) return false;
  const parts = name.slice(0, dot).split(/[.-]/);
  if (!parts[0]) return false;
  return parts.slice(1).some(
    (part) => /^[0-9a-f]{8,64}$/.test(part) && /[0-9]/.test(part) && /[a-f]/.test(part),
  );
}

async function store(request, response) {
  if (!storable(response)) return;
  try {
    const cache = await caches.open(CACHE);
    await cache.put(request, response.clone());
  } catch (error) {
    // A full or unavailable cache only costs the offline copy.
  }
}

async function precache() {
  const cache = await caches.open(CACHE);
  await Promise.all(
    PRECACHE.map(async (url) => {
      const response = await fetch(url, { cache: 'no-cache', credentials: 'same-origin' }).catch(() => null);
      if (storable(response)) {
        await cache.put(url, response);
      } else if (url === OFFLINE_URL) {
        throw new Error('the offline page must answer 200 without no-store or private');
      }
    }),
  );
}

async function networkFirst(request, fallback) {
  try {
    const response = await fetch(request);
    await store(request, response);
    return response;
  } catch (error) {
    const cached = await caches.match(request);
    if (cached) return cached;
    if (fallback) {
      const offline = await caches.match(fallback);
      if (offline) return offline;
    }
    throw error;
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  await store(request, response);
  return response;
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((names) =>
        Promise.all(
          names
            .filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE)
            .map((name) => caches.delete(name)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, OFFLINE_URL));
  } else if (url.pathname.startsWith('/static/')) {
    event.respondWith(isVersioned(url.pathname) ? cacheFirst(request) : networkFirst(request, null));
  }
  // Every other request (forms, htmx fragments, APIs) goes to the network untouched.
});

// The page's reload button asks the waiting worker to take over.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});
